import React, { useEffect, useState } from "react";

export default function AdminDashboard() {
  const [users, setUsers] = useState([]);
  const [error, setError] = useState("");
  const [editingUser, setEditingUser] = useState(null); // stores user currently being edited
  const [editEmail, setEditEmail] = useState("");
  const [editDisabled, setEditDisabled] = useState(false);

  const API_BASE_URL = "http://localhost:5000";

  const fetchUsers = async () => {
    try {
      const res = await fetch(`${API_BASE_URL}/users`);
      if (!res.ok) throw new Error("Failed to fetch users");
      const data = await res.json();
      setUsers(data);
    } catch (err) {
      setError(err.message);
    }
  };

  useEffect(() => {
    fetchUsers();
  }, []);

  const handleDelete = async (uid) => {
    try {
      const res = await fetch(`${API_BASE_URL}/users/${uid}`, { method: "DELETE" });
      if (!res.ok) throw new Error("Failed to delete user");
      fetchUsers();
    } catch (err) {
      setError(err.message);
    }
  };

  // Start editing user - open edit form
  const startEdit = (user) => {
    setEditingUser(user);
    setEditEmail(user.email);
    setEditDisabled(user.disabled || false);
  };

  // Cancel edit
  const cancelEdit = () => {
    setEditingUser(null);
    setError("");
  };

  // Submit updated user info
  const submitEdit = async () => {
    try {
      const res = await fetch(`${API_BASE_URL}/users/${editingUser.uid}`, {
        method: "PUT",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ email: editEmail, disabled: editDisabled }),
      });
      if (!res.ok) throw new Error("Failed to update user");
      setEditingUser(null);
      fetchUsers();
    } catch (err) {
      setError(err.message);
    }
  };

  return (
    <div style={{ padding: "20px" }}>
      <h2>Admin User Management</h2>
      {error && <p style={{ color: "red" }}>{error}</p>}
      <table border="1" cellPadding="10" style={{ width: "100%", borderCollapse: "collapse" }}>
        <thead>
          <tr>
            <th>UID</th>
            <th>Email</th>
            <th>Display Name</th>
            <th>Disabled</th>
            <th>Actions</th>
          </tr>
        </thead>
        <tbody>
          {users.map((user) =>
            editingUser && editingUser.uid === user.uid ? (
              <tr key={user.uid}>
                <td>{user.uid}</td>
                <td>
                  <input
                    value={editEmail}
                    onChange={(e) => setEditEmail(e.target.value)}
                  />
                </td>
                <td>{user.displayName || "-"}</td>
                <td>
                  <input
                    type="checkbox"
                    checked={editDisabled}
                    onChange={(e) => setEditDisabled(e.target.checked)}
                  />
                </td>
                <td>
                  <button onClick={submitEdit} style={{ marginRight: 8 }}>Save</button>
                  <button onClick={cancelEdit}>Cancel</button>
                </td>
              </tr>
            ) : (
              <tr key={user.uid}>
                <td>{user.uid}</td>
                <td>{user.email}</td>
                <td>{user.displayName || "-"}</td>
                <td>{user.disabled ? "Yes" : "No"}</td>
                <td>
                  <button onClick={() => startEdit(user)} style={{ marginRight: 8 }}>Edit</button>
                  <button onClick={() => handleDelete(user.uid)} style={{ color: "red" }}>
                    Delete
                  </button>
                </td>
              </tr>
            )
          )}
        </tbody>
      </table>
    </div>
  );
}
